spec.setup_code:
var INK='#04204B', SEC='#3D5F91', GUIDE='#8098BC', BLUE='#2F6FD0', AMB='#E3A21A', TEAL='#138374', WARM='#B4552F', VIO='#6A47C2';
var load=[[0,40.5],[2,37.5],[4,37.2],[6,38.6],[8,44.2],[10,47.5],[12,47.7],[14,44.5],[16,43.8],[18,46.3],[20,46.2],[22,43.9],[24,40.5]];
var wind=[[0,14],[4,13.5],[8,10],[12,10.3],[16,11.2],[20,13.2],[24,14]];
var solar=[[0,0],[5,0],[6,2.4],[8,16.6],[10,28.8],[12,32],[14,30],[16,23.5],[18,10.6],[20,0.8],[21,0],[24,0]];
var resid=[[0,26.4],[4,23.7],[6,23.3],[8,17.6],[10,8.8],[12,5.4],[14,5.0],[16,9.1],[18,21.9],[20,32.1],[22,29.1],[24,26.5]];
var price=[[0,88],[2,78],[4,76],[6,73],[8,45],[10,-1],[12,-31],[14,-43],[16,-3],[18,76],[20,126],[22,107],[24,88]];
function F(p,h){ if(h<=p[0][0]) return p[0][1]; for(var i=1;i<p.length;i++){ if(h<=p[i][0]){ var a=p[i-1],b=p[i]; return a[1]+(b[1]-a[1])*(h-a[0])/(b[0]-a[0]); } } return p[p.length-1][1]; }
function clamp(v,a,b){ return Math.max(a,Math.min(b,v)); }
function pad2(n){ return (n<10?'0':'')+n; }
function fmt(n){ var k=Math.round(n/1000); return k>=1?k+',000':'0'; }
function txt(c,s,x,y,col,al,font){ c.fillStyle=col; c.textAlign=al||'left'; c.font=font||'12px sans-serif'; c.fillText(s,x,y); }
function vh(p){ if(p<0.4) return 12; if(p<2.2) return 12+2*(p-0.4)/1.8; if(p<2.8) return 14+5*(p-2.2)/0.6; if(p<4.6) return 19+2*(p-2.8)/1.8; return 21; }
return { draw: function(c,width,height,time,dt){
 c.fillStyle='#ffffff'; c.fillRect(0,0,width,height);
 var t=time%20, ph2=t>=14, p=ph2?t-14:0;
 var cur=ph2?24:clamp(24*t/14,0,24);
 var hv=ph2?vh(p):cur;
 var L=52, R=16, W=width-L-R;
 var topY0=44, topY1=Math.round(height*0.43), botY0=topY1+38, botY1=height-106;
 function X(h){ return L+h/24*W; }
 function yT(v){ return topY1-v/60*(topY1-topY0); }
 function yB(v){ return botY1-(v+60)/200*(botY1-botY0); }
 c.lineCap='round'; c.lineJoin='round';
 c.font='12px sans-serif';
 var lx=L, ly=14;
 var leg=[['Load',INK,0],['Wind',BLUE,1],['Solar (stacked)',AMB,1],['Residual load',TEAL,2]];
 for(var i=0;i<leg.length;i++){
  var it=leg[i];
  if(it[2]===1){ c.fillStyle=it[1]; c.globalAlpha=0.7; c.fillRect(lx,ly-9,16,10); c.globalAlpha=1; }
  else { c.strokeStyle=it[1]; c.lineWidth=2.4; c.setLineDash(it[2]===2?[5,3]:[]); c.beginPath(); c.moveTo(lx,ly-4); c.lineTo(lx+16,ly-4); c.stroke(); c.setLineDash([]); }
  txt(c,it[0],lx+22,ly,INK,'left');
  lx+=22+c.measureText(it[0]).width+18;
 }
 txt(c,'Power (GW)',L,topY0-10,SEC,'left');
 txt(c,'Day-ahead price (EUR/MWh)',L,botY0-10,SEC,'left');
 txt(c,(ph2?'phase 2: battery':'phase 1: sweeping the day')+'  |  hour '+pad2(Math.floor(hv))+':'+pad2(Math.floor((hv-Math.floor(hv))*60)),width-R,topY0-10,INK,'right');
 c.lineWidth=1;
 var gt=[0,20,40,60];
 for(i=0;i<gt.length;i++){ c.strokeStyle=GUIDE; c.globalAlpha=0.3; c.beginPath(); c.moveTo(L,yT(gt[i])); c.lineTo(L+W,yT(gt[i])); c.stroke(); c.globalAlpha=1; txt(c,String(gt[i]),L-6,yT(gt[i])+4,SEC,'right'); }
 var gb=[-50,0,50,100];
 for(i=0;i<gb.length;i++){ c.strokeStyle=GUIDE; c.globalAlpha=(gb[i]===0?0.8:0.3); c.beginPath(); c.moveTo(L,yB(gb[i])); c.lineTo(L+W,yB(gb[i])); c.stroke(); c.globalAlpha=1; txt(c,String(gb[i]),L-6,yB(gb[i])+4,SEC,'right'); }
 c.strokeStyle=GUIDE; c.beginPath(); c.moveTo(L,topY0); c.lineTo(L,topY1); c.lineTo(L+W,topY1); c.stroke();
 c.beginPath(); c.moveTo(L,botY0); c.lineTo(L,botY1); c.lineTo(L+W,botY1); c.stroke();
 for(var h=0;h<=24;h+=4){ txt(c,h+'h',X(h),topY1+14,SEC,'center'); txt(c,h+'h',X(h),botY1+14,SEC,'center'); }
 if(ph2){
  if(p>=0.4){ c.fillStyle='rgba(19,131,116,0.14)'; c.fillRect(X(12),botY0,X(14)-X(12),botY1-botY0); txt(c,'charge',X(13),botY0+12,TEAL,'center'); }
  if(p>=2.8){ c.fillStyle='rgba(180,85,47,0.12)'; c.fillRect(X(19),botY0,X(21)-X(19),botY1-botY0); txt(c,'discharge',X(20),botY0+12,WARM,'center'); }
 }
 var hs=[]; for(var k=0;k*0.25<cur;k++) hs.push(k*0.25); hs.push(cur);
 var n=hs.length;
 c.beginPath(); c.moveTo(X(0),yT(0));
 for(i=0;i<n;i++) c.lineTo(X(hs[i]),yT(F(wind,hs[i])));
 c.lineTo(X(cur),yT(0)); c.closePath(); c.fillStyle='rgba(47,111,208,0.55)'; c.fill();
 c.beginPath(); c.moveTo(X(0),yT(F(wind,0)));
 for(i=0;i<n;i++) c.lineTo(X(hs[i]),yT(F(wind,hs[i])+F(solar,hs[i])));
 for(i=n-1;i>=0;i--) c.lineTo(X(hs[i]),yT(F(wind,hs[i])));
 c.closePath(); c.fillStyle='rgba(227,162,26,0.65)'; c.fill();
 c.strokeStyle=INK; c.lineWidth=2.4; c.beginPath();
 var xx, yy;
 for(i=0;i<n;i++){ xx=X(hs[i]); yy=yT(F(load,hs[i])); if(i===0) c.moveTo(xx,yy); else c.lineTo(xx,yy); }
 c.stroke();
 c.strokeStyle=TEAL; c.lineWidth=2.6; c.setLineDash([6,4]); c.beginPath();
 for(i=0;i<n;i++){ xx=X(hs[i]); yy=yT(F(resid,hs[i])); if(i===0) c.moveTo(xx,yy); else c.lineTo(xx,yy); }
 c.stroke(); c.setLineDash([]);
 c.beginPath(); c.moveTo(X(0),yB(0));
 for(i=0;i<n;i++) c.lineTo(X(hs[i]),yB(Math.min(F(price,hs[i]),0)));
 c.lineTo(X(cur),yB(0)); c.closePath(); c.fillStyle='rgba(47,111,208,0.22)'; c.fill();
 c.strokeStyle=WARM; c.lineWidth=2.4; c.beginPath();
 for(i=0;i<n;i++){ xx=X(hs[i]); yy=yB(F(price,hs[i])); if(i===0) c.moveTo(xx,yy); else c.lineTo(xx,yy); }
 c.stroke();
 var a1=ph2?1:clamp((cur-11)/1.2,0,1);
 if(a1>0){ c.globalAlpha=a1; txt(c,'negative prices:',X(10.4),yB(-20),BLUE,'right'); txt(c,'producers pay to deliver',X(10.4),yB(-20)+15,BLUE,'right'); c.globalAlpha=1; }
 c.strokeStyle=INK; c.globalAlpha=0.35; c.lineWidth=1; c.beginPath(); c.moveTo(X(hv),topY0); c.lineTo(X(hv),topY1); c.moveTo(X(hv),botY0); c.lineTo(X(hv),botY1); c.stroke(); c.globalAlpha=1;
 var dots=[[load,INK,yT],[resid,TEAL,yT],[price,WARM,yB]];
 for(i=0;i<3;i++){ c.fillStyle=dots[i][1]; c.beginPath(); c.arc(X(hv),dots[i][2](F(dots[i][0],hv)),3.5,0,6.283); c.fill(); }
 var ty=topY0+12;
 var a2=ph2?1:clamp((cur-14.2)/1.0,0,1);
 if(a2>0){
  c.globalAlpha=a2; c.strokeStyle=TEAL; c.lineWidth=1; c.setLineDash([3,3]); c.beginPath(); c.moveTo(X(14),yT(5)-5); c.lineTo(X(14),ty+4); c.stroke(); c.setLineDash([]);
  c.fillStyle=TEAL; c.beginPath(); c.arc(X(14),yT(5),4.5,0,6.283); c.fill();
  txt(c,"duck's belly: residual load 5 GW at 14:00",X(15),ty,TEAL,'right','bold 12px sans-serif'); c.globalAlpha=1;
 }
 var a3=ph2?1:clamp((cur-20.2)/1.0,0,1);
 if(a3>0){
  c.globalAlpha=a3; c.strokeStyle=VIO; c.lineWidth=2; c.beginPath(); c.moveTo(X(14),yT(5)); c.lineTo(X(20),yT(32.1)); c.stroke();
  c.lineWidth=1; c.setLineDash([3,3]); c.beginPath(); c.moveTo(X(20),yT(32.1)-5); c.lineTo(X(20),ty+4); c.stroke(); c.setLineDash([]);
  c.fillStyle=VIO; c.beginPath(); c.arc(X(20),yT(32.1),4.5,0,6.283); c.fill();
  txt(c,'evening ramp: +27 GW in 6 hours',X(24),ty,VIO,'right','bold 12px sans-serif'); c.globalAlpha=1;
 }
 var sy=height-90;
 var cf=ph2?clamp((p-0.4)/1.8,0,1):0, df=ph2?clamp((p-2.8)/1.8,0,1):0;
 var soc=cf-df;
 var charging=ph2&&p>=0.4&&p<2.2, disch=ph2&&p>=2.8&&p<4.6;
 txt(c,'A 1 GW / 2 GWh battery',L,sy+12,ph2?INK:SEC,'left','bold 12px sans-serif');
 var bx=L+52, by=sy+26, bw=70, bh=28;
 c.globalAlpha=ph2?1:0.45;
 c.strokeStyle=INK; c.lineWidth=2; c.strokeRect(bx,by,bw,bh); c.fillStyle=INK; c.fillRect(bx+bw,by+8,5,bh-16);
 if(soc>0){ c.fillStyle=disch?WARM:TEAL; c.fillRect(bx+3,by+3,(bw-6)*soc,bh-6); }
 c.globalAlpha=1;
 txt(c,'stored '+(2*soc).toFixed(1)+' GWh',bx+bw/2,by+bh+15,SEC,'center');
 var flow=charging||disch;
 if(flow){
  for(k=0;k<3;k++){
   var f=((k/3)+p*1.4)%1, ax=charging?(L+f*44):(bx+bw+10+f*44), ay=by+bh/2;
   c.fillStyle=charging?TEAL:WARM; c.globalAlpha=0.9;
   c.beginPath(); c.moveTo(ax,ay-6); c.lineTo(ax+9,ay); c.lineTo(ax,ay+6); c.closePath(); c.fill(); c.globalAlpha=1;
  }
  txt(c,charging?'1 GW in':'1 GW out',charging?L+22:bx+bw+34,by-4,charging?TEAL:WARM,'center');
 }
 var tx=L+205;
 if(!ph2){
  txt(c,'Phase 2 follows: buy cheap power at the belly, sell at the evening peak.',tx,sy+44,SEC,'left');
 } else {
  if(p>=0.4) txt(c,'buys 2 GWh at about -35 EUR/MWh: is paid 70,000 EUR',tx,sy+30,TEAL,'left');
  if(p>=2.8) txt(c,'sells 2 GWh at about 120 EUR/MWh: 240,000 EUR',tx,sy+48,WARM,'left');
  var run=70000*cf+240000*df;
  if(p<4.6) txt(c,'running total: '+fmt(run)+' EUR',tx,sy+68,INK,'left','bold 12px sans-serif');
  else txt(c,'spread captured about 310,000 EUR minus losses (~15 %)',tx,sy+68,INK,'left','bold 12px sans-serif');
 }
}};
